{$ param title label="Title" default="Page Title" description="Main page heading." $}
{$ param subtitle label="Subtitle" default="" description="Short tagline under the title." $}

<header class="text-center mb-8 max-w-[960px] mx-auto">
  <h1 class="ss-large mb-2">{$= title $}</h1>
  {$ if subtitle $}<p class="ss-small text-neutral-dark mb-4">{$= subtitle $}</p>{$ /if $}
  {$ slot intro $}
    <p class="ss-text">Intro paragraph.</p>
  {$ /slot $}
</header>
